// Replicated state (CRDT).
//
// Every entity (element/connector or layer) keeps one last-writer-wins register
// per field, stamped with (clock, actor). Creation and deletion are stamped too:
// an entity is alive when its newest creation stamp is newer than its newest
// deletion stamp. Because every merge is a max() over stamps, the result does
// not depend on delivery order and duplicates are harmless (ops are also keyed
// by opId and ignored once seen).
import { DiagramError } from './errors.js';

export const DEFAULT_LAYER = 'default';
export const KIND_EL = 'el';
export const KIND_LAYER = 'layer';

export function newState() {
  return { clock: 0, entities: {}, seen: {} };
}

// Total order on stamps: by clock, then by actor id.
export function cmpStamp(a, b) {
  if (a.clock !== b.clock) return a.clock - b.clock;
  if (a.actor === b.actor) return 0;
  return a.actor < b.actor ? -1 : 1;
}

function maxStamp(a, b) {
  if (!a) return b;
  return cmpStamp(a, b) >= 0 ? a : b;
}

export function entityKey(kind, id) {
  return kind + '|' + id;
}

// Apply one wire operation. Returns true when the op was new.
export function applyWire(state, op) {
  if (!op || typeof op !== 'object') throw new DiagramError('invalid operation');
  if (typeof op.opId !== 'string') throw new DiagramError('operation without opId');
  if (typeof op.clock !== 'number' || typeof op.actor !== 'string') {
    throw new DiagramError('operation without stamp');
  }
  if (op.kind !== KIND_EL && op.kind !== KIND_LAYER) throw new DiagramError('invalid kind');
  if (typeof op.id !== 'string') throw new DiagramError('invalid id');
  if (state.seen[op.opId]) return false;
  state.seen[op.opId] = true;
  if (op.clock > state.clock) state.clock = op.clock;

  const stamp = { clock: op.clock, actor: op.actor };
  const key = entityKey(op.kind, op.id);
  let ent = state.entities[key];
  if (!ent) {
    ent = state.entities[key] = { kind: op.kind, id: op.id, fields: {}, created: null, deleted: null };
  }
  if (op.type === 'put') {
    if (!op.fields || typeof op.fields !== 'object') throw new DiagramError('put without fields');
    for (const f of Object.keys(op.fields)) {
      const cur = ent.fields[f];
      if (!cur || cmpStamp(stamp, cur) > 0) {
        const v = op.fields[f];
        ent.fields[f] = { v: v === undefined ? null : v, clock: op.clock, actor: op.actor };
      }
    }
    if (op.create) ent.created = maxStamp(ent.created, stamp);
  } else if (op.type === 'del') {
    ent.deleted = maxStamp(ent.deleted, stamp);
  } else {
    throw new DiagramError(`unknown wire operation: ${op.type}`);
  }
  return true;
}

export function isAlive(ent) {
  if (!ent || !ent.created) return false;
  return !ent.deleted || cmpStamp(ent.created, ent.deleted) > 0;
}

// Raw register values of an entity, as plain data.
export function rawFields(ent) {
  const out = {};
  for (const [f, r] of Object.entries(ent.fields)) out[f] = structuredClone(r.v);
  return out;
}

// Materialise an alive entity as a plain object (style keys are merged).
export function materialize(ent) {
  const o = { id: ent.id };
  const style = {};
  for (const [f, r] of Object.entries(ent.fields)) {
    if (r.v === null || r.v === undefined) continue;
    if (f.startsWith('style.')) style[f.slice(6)] = structuredClone(r.v);
    else o[f] = structuredClone(r.v);
  }
  if (ent.kind === KIND_LAYER) {
    if (o.visible === undefined) o.visible = true;
    if (o.locked === undefined) o.locked = false;
    if (o.order === undefined) o.order = 0;
    return o;
  }
  o.style = style;
  if (o.type === 'connector') {
    if (o.routing === undefined) o.routing = 'straight';
    if (o.waypoints === undefined) o.waypoints = [];
  } else {
    for (const k of ['x', 'y', 'width', 'height', 'rotation']) if (o[k] === undefined) o[k] = 0;
    if (o.z === undefined) o.z = 0;
  }
  if (o.layer === undefined) o.layer = DEFAULT_LAYER;
  if (o.groupId === undefined) o.groupId = null;
  return o;
}

