    x0 = Math.min(x0, b.x);
    y0 = Math.min(y0, b.y);
    x1 = Math.max(x1, b.x + b.width);
    y1 = Math.max(y1, b.y + b.height);
  }
  return { x: x0, y: y0, width: x1 - x0, height: y1 - y0 };
}

// Point-in-shape test in the shape's own (unrotated) frame.
export function containsPoint(o, px, py) {
  const c = centerOf(o);
  const p = o.rotation ? rotatePoint(px, py, c.x, c.y, -o.rotation) : { x: px, y: py };
  const dx = p.x - c.x;
  const dy = p.y - c.y;
  const hw = o.width / 2;
  const hh = o.height / 2;
  if (o.type === 'ellipse') {
    const a = Math.max(hw, 1e-9);
    const b = Math.max(hh, 1e-9);
    return (dx * dx) / (a * a) + (dy * dy) / (b * b) <= 1;
  }
  if (o.type === 'diamond') {
    return Math.abs(dx) / Math.max(hw, 1e-9) + Math.abs(dy) / Math.max(hh, 1e-9) <= 1;
  }
  if (o.type === 'line') {
    // distance from point to the diagonal (x,y)-(x+w,y+h) in local coordinates
    const lx = p.x - o.x;
    const ly = p.y - o.y;
    const len2 = o.width * o.width + o.height * o.height;
    let t = len2 ? (lx * o.width + ly * o.height) / len2 : 0;
    t = Math.max(0, Math.min(1, t));
    const ex = o.width * t - lx;
    const ey = o.height * t - ly;
    return Math.hypot(ex, ey) <= 5;
  }
  return Math.abs(dx) <= hw && Math.abs(dy) <= hh;
}

// Snap a point ({x,y} or [x,y]) to guide lines (within threshold) and then to a grid.
// guides: {x:[...], y:[...]} or [{x}|{y}|{axis,value}] or [number] (x-guides).
export function snap(point, opts = {}) {
  const isArr = Array.isArray(point);
  let x = isArr ? point[0] : point.x;
  let y = isArr ? point[1] : point.y;
  if (typeof x !== 'number' || typeof y !== 'number' || !Number.isFinite(x) || !Number.isFinite(y)) {
    throw new DiagramError('snap: invalid point');
  }
  const threshold = opts.threshold ?? 5;
  const gx = [];
  const gy = [];
  const g = opts.guides;
  if (g && !Array.isArray(g)) {
    for (const v of g.x ?? []) gx.push(v);
    for (const v of g.y ?? []) gy.push(v);
  } else if (Array.isArray(g)) {
    for (const item of g) {
      if (typeof item === 'number') gx.push(item);
      else if (item && item.axis === 'y') gy.push(item.value);
      else if (item && item.axis === 'x') gx.push(item.value);
      else if (item && typeof item.y === 'number') gy.push(item.y);
      else if (item && typeof item.x === 'number') gx.push(item.x);
    }
  }
  const nearest = (v, list) => {
    let best = null;
    for (const g0 of list) {
      const d = Math.abs(v - g0);
      if (d <= threshold && (best === null || d < Math.abs(v - best))) best = g0;
    }
    return best;
  };
  const gridRound = (v) => (opts.grid > 0 ? Math.round(v / opts.grid) * opts.grid : v);
  const sx = nearest(x, gx);
  const sy = nearest(y, gy);
  x = sx !== null ? sx : gridRound(x);
  y = sy !== null ? sy : gridRound(y);
  return isArr ? [x, y] : { ...point, x, y };
}

