// Error type used by every core API. Subclass of Error so `instanceof Error` holds.
export class DiagramError extends Error {
  constructor(message) {
    super(message);
    this.name = 'DiagramError';
  }
}

// Replicated state (CRDT).
//
// Every entity (element/connector or layer) keeps one last-writer-wins register
// per field, stamped with (clock, actor). Creation and deletion are stamped too:
// an entity is alive when its newest creation stamp is newer than its newest
// deletion stamp. Because every merge is a max() over stamps, the result does
// not depend on delivery order and duplicates are harmless (ops are also keyed
// by opId and ignored once seen).
import { DiagramError } from './errors.js';

export const DEFAULT_LAYER = 'default';
export const KIND_EL = 'el';
export const KIND_LAYER = 'layer';

export function newState() {
  return { clock: 0, entities: {}, seen: {} };
}

// Total order on stamps: by clock, then by actor id.
export function cmpStamp(a, b) {
  if (a.clock !== b.clock) return a.clock - b.clock;
  if (a.actor === b.actor) return 0;
  return a.actor < b.actor ? -1 : 1;
}

function maxStamp(a, b) {
  if (!a) return b;
  return cmpStamp(a, b) >= 0 ? a : b;
}

export function entityKey(kind, id) {
  return kind + '|' + id;
}

// Apply one wire operation. Returns true when the op was new.
export function applyWire(state, op) {
  if (!op || typeof op !== 'object') throw new DiagramError('invalid operation');
  if (typeof op.opId !== 'string') throw new DiagramError('operation without opId');
  if (typeof op.clock !== 'number' || typeof op.actor !== 'string') {
    throw new DiagramError('operation without stamp');
  }
  if (op.kind !== KIND_EL && op.kind !== KIND_LAYER) throw new DiagramError('invalid kind');
  if (typeof op.id !== 'string') throw new DiagramError('invalid id');
  if (state.seen[op.opId]) return false;
  state.seen[op.opId] = true;
  if (op.clock > state.clock) state.clock = op.clock;

  const stamp = { clock: op.clock, actor: op.actor };
  const key = entityKey(op.kind, op.id);
  let ent = state.entities[key];
  if (!ent) {
    ent = state.entities[key] = { kind: op.kind, id: op.id, fields: {}, created: null, deleted: null };
  }
  if (op.type === 'put') {
    if (!op.fields || typeof op.fields !== 'object') throw new DiagramError('put without fields');
    for (const f of Object.keys(op.fields)) {
      const cur = ent.fields[f];
      if (!cur || cmpStamp(stamp, cur) > 0) {
        const v = op.fields[f];
        ent.fields[f] = { v: v === undefined ? null : v, clock: op.clock, actor: op.actor };
      }
    }
    if (op.create) ent.created = maxStamp(ent.created, stamp);
  } else if (op.type === 'del') {
    ent.deleted = maxStamp(ent.deleted, stamp);
  } else {
    throw new DiagramError(`unknown wire operation: ${op.type}`);
  }
  return true;
}

export function isAlive(ent) {
  if (!ent || !ent.created) return false;
  return !ent.deleted || cmpStamp(ent.created, ent.deleted) > 0;
}

// Raw register values of an entity, as plain data.
export function rawFields(ent) {
  const out = {};
  for (const [f, r] of Object.entries(ent.fields)) out[f] = structuredClone(r.v);
  return out;
}

// Materialise an alive entity as a plain object (style keys are merged).
export function materialize(ent) {
  const o = { id: ent.id };
  const style = {};
  for (const [f, r] of Object.entries(ent.fields)) {
    if (r.v === null || r.v === undefined) continue;
    if (f.startsWith('style.')) style[f.slice(6)] = structuredClone(r.v);
    else o[f] = structuredClone(r.v);
  }
  if (ent.kind === KIND_LAYER) {
    if (o.visible === undefined) o.visible = true;
    if (o.locked === undefined) o.locked = false;
    if (o.order === undefined) o.order = 0;
    return o;
  }
  o.style = style;
  if (o.type === 'connector') {
    if (o.routing === undefined) o.routing = 'straight';
    if (o.waypoints === undefined) o.waypoints = [];
  } else {
    for (const k of ['x', 'y', 'width', 'height', 'rotation']) if (o[k] === undefined) o[k] = 0;
    if (o.z === undefined) o.z = 0;
  }
  if (o.layer === undefined) o.layer = DEFAULT_LAYER;
  if (o.groupId === undefined) o.groupId = null;
  return o;
}

// Geometry helpers: rotation-aware bounding boxes, hit tests, snapping.
import { DiagramError } from './errors.js';

export function centerOf(o) {
  return { x: o.x + o.width / 2, y: o.y + o.height / 2 };
}

// Rotate point (px,py) about (cx,cy) by deg degrees (clockwise in screen coordinates).
export function rotatePoint(px, py, cx, cy, deg) {
  const r = (deg * Math.PI) / 180;
  const c = Math.cos(r);
  const s = Math.sin(r);
  const dx = px - cx;
  const dy = py - cy;
  return { x: cx + dx * c - dy * s, y: cy + dx * s + dy * c };
}

// Axis-aligned bounding box of a (possibly rotated) shape.
export function bboxOf(o) {
  if (!o.rotation) return { x: o.x, y: o.y, width: o.width, height: o.height };
  const c = centerOf(o);
  const corners = [
    [o.x, o.y],
    [o.x + o.width, o.y],
    [o.x + o.width, o.y + o.height],
    [o.x, o.y + o.height],
  ].map(([px, py]) => rotatePoint(px, py, c.x, c.y, o.rotation));
  const xs = corners.map((p) => p.x);
  const ys = corners.map((p) => p.y);
  const minX = Math.min(...xs);
  const minY = Math.min(...ys);
  return { x: minX, y: minY, width: Math.max(...xs) - minX, height: Math.max(...ys) - minY };
}

export function unionBox(boxes) {
  if (!boxes.length) return null;
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const b of boxes) {
    x0 = Math.min(x0, b.x);
    y0 = Math.min(y0, b.y);
    x1 = Math.max(x1, b.x + b.width);
    y1 = Math.max(y1, b.y + b.height);
  }
  return { x: x0, y: y0, width: x1 - x0, height: y1 - y0 };
}

// Point-in-shape test in the shape's own (unrotated) frame.
export function containsPoint(o, px, py) {
  const c = centerOf(o);
  const p = o.rotation ? rotatePoint(px, py, c.x, c.y, -o.rotation) : { x: px, y: py };
  const dx = p.x - c.x;
  const dy = p.y - c.y;
  const hw = o.width / 2;
  const hh = o.height / 2;
  if (o.type === 'ellipse') {
    const a = Math.max(hw, 1e-9);
    const b = Math.max(hh, 1e-9);
    return (dx * dx) / (a * a) + (dy * dy) / (b * b) <= 1;
  }
  if (o.type === 'diamond') {
    return Math.abs(dx) / Math.max(hw, 1e-9) + Math.abs(dy) / Math.max(hh, 1e-9) <= 1;
  }
  if (o.type === 'line') {
    // distance from point to the diagonal (x,y)-(x+w,y+h) in local coordinates
    const lx = p.x - o.x;
    const ly = p.y - o.y;
    const len2 = o.width * o.width + o.height * o.height;
    let t = len2 ? (lx * o.width + ly * o.height) / len2 : 0;
    t = Math.max(0, Math.min(1, t));
    const ex = o.width * t - lx;
    const ey = o.height * t - ly;
    return Math.hypot(ex, ey) <= 5;
  }
  return Math.abs(dx) <= hw && Math.abs(dy) <= hh;
}

// Snap a point ({x,y} or [x,y]) to guide lines (within threshold) and then to a grid.
// guides: {x:[...], y:[...]} or [{x}|{y}|{axis,value}] or [number] (x-guides).
export function snap(point, opts = {}) {
  const isArr = Array.isArray(point);
  let x = isArr ? point[0] : point.x;
  let y = isArr ? point[1] : point.y;
  if (typeof x !== 'number' || typeof y !== 'number' || !Number.isFinite(x) || !Number.isFinite(y)) {
    throw new DiagramError('snap: invalid point');
  }
  const threshold = opts.threshold ?? 5;
  const gx = [];
  const gy = [];
  const g = opts.guides;
  if (g && !Array.isArray(g)) {
    for (const v of g.x ?? []) gx.push(v);
    for (const v of g.y ?? []) gy.push(v);
  } else if (Array.isArray(g)) {
    for (const item of g) {
      if (typeof item === 'number') gx.push(item);
      else if (item && item.axis === 'y') gy.push(item.value);
      else if (item && item.axis === 'x') gx.push(item.value);
      else if (item && typeof item.y === 'number') gy.push(item.y);
      else if (item && typeof item.x === 'number') gx.push(item.x);
    }
  }
  const nearest = (v, list) => {
    let best = null;
    for (const g0 of list) {
      const d = Math.abs(v - g0);
      if (d <= threshold && (best === null || d < Math.abs(v - best))) best = g0;
    }
    return best;
  };
  const gridRound = (v) => (opts.grid > 0 ? Math.round(v / opts.grid) * opts.grid : v);
  const sx = nearest(x, gx);
  const sy = nearest(y, gy);
  x = sx !== null ? sx : gridRound(x);
  y = sy !== null ? sy : gridRound(y);
  return isArr ? [x, y] : { ...point, x, y };
}

