// Connector routing.
//  - straight: centre-to-centre polyline clipped to the shape boundaries.
//  - orthogonal: shortest axis-parallel path on the Hanan grid (all shape-box
//    edges + endpoints + a 100px margin) that never crosses a shape interior.
//    Dijkstra over (node, direction) states with a bend penalty.
import { bboxOf, centerOf, containsPoint, rotatePoint } from './geometry.js';

const MARGIN = 100;
const BEND_PENALTY = 40;
const SIDES = ['top', 'right', 'bottom', 'left'];

export function computeRoute(conn, els) {
  const src = els.get(conn.source.elementId);
  const tgt = els.get(conn.target.elementId);
  if (!src || !tgt) return [];
  const wps = (conn.waypoints ?? []).map((p) => [p[0], p[1]]);
  const shapes = [...els.values()].filter((e) => e.type !== 'connector');
  const boxes = shapes.map(bboxOf);
  if (conn.routing === 'orthogonal') {
    return orthogonalRoute(conn, src, tgt, wps, boxes);
  }
  return straightRoute(conn, src, tgt, wps);
}

function sidePoint(shape, side) {
  const b = bboxOf({ ...shape, rotation: 0 });
  const c = centerOf(shape);
  let p;
  if (side === 'top') p = { x: b.x + b.width / 2, y: b.y };
  else if (side === 'bottom') p = { x: b.x + b.width / 2, y: b.y + b.height };
  else if (side === 'left') p = { x: b.x, y: b.y + b.height / 2 };
  else if (side === 'right') p = { x: b.x + b.width, y: b.y + b.height / 2 };
  else p = c;
  if (shape.rotation) p = rotatePoint(p.x, p.y, c.x, c.y, shape.rotation);
  return [p.x, p.y];
}

function portOf(port) {
  if (port === undefined || port === null) return null;
  if (SIDES.includes(port) || port === 'center') return port;
  return null;
}

// Clip the segment from an inside point (the shape centre) toward `outer` at the boundary.
function clipToBoundary(shape, inner, outer) {
  if (!containsPoint(shape, outer[0], outer[1]) === false) {
    // outer point inside the same shape: nothing to clip against
    return inner;
  }
  let lo = 0;
  let hi = 1;
  const at = (t) => [inner[0] + (outer[0] - inner[0]) * t, inner[1] + (outer[1] - inner[1]) * t];
  for (let i = 0; i < 40; i++) {
    const mid = (lo + hi) / 2;
    const [mx, my] = at(mid);
    if (containsPoint(shape, mx, my)) lo = mid;
    else hi = mid;
  }
  return at((lo + hi) / 2);
}

function straightRoute(conn, src, tgt, wps) {
  const sPort = portOf(conn.source.port);
  const tPort = portOf(conn.target.port);
  const cs = [centerOf(src).x, centerOf(src).y];
  const ct = [centerOf(tgt).x, centerOf(tgt).y];
  let start;
  let end;
  if (sPort && sPort !== 'center') start = sidePoint(src, sPort);
  else if (sPort === 'center') start = cs;
  else start = clipToBoundary(src, cs, wps[0] ?? ct);
  if (tPort && tPort !== 'center') end = sidePoint(tgt, tPort);
  else if (tPort === 'center') end = ct;
  else end = clipToBoundary(tgt, ct, wps.length ? wps[wps.length - 1] : cs);
  return dedupe([start, ...wps, end]);
}

function sideCandidates(shape, port) {
  if (port && SIDES.includes(port)) return [sidePoint(shape, port)];
  return SIDES.map((s) => sidePoint(shape, s));
}

function orthogonalRoute(conn, src, tgt, wps, boxes) {
  const sPort = portOf(conn.source.port);
  const tPort = portOf(conn.target.port);
  const anchors = [{ shape: src, port: sPort }, ...wps.map((p) => ({ pt: p })), { shape: tgt, port: tPort }];
  const out = [];
  for (let i = 0; i < anchors.length - 1; i++) {
    const A = anchors[i];
    const B = anchors[i + 1];
    const starts = A.shape ? sideCandidates(A.shape, A.port) : [A.pt];
    const goals = B.shape ? sideCandidates(B.shape, B.port) : [B.pt];
    const extra = [...starts, ...goals];
    let seg = gridRoute(starts, goals, boxes, extra);
    if (!seg) seg = [starts[0], [goals[0][0], starts[0][1]], goals[0]];
    if (out.length) seg = seg.slice(1);
    out.push(...seg);
  }
  return simplify(dedupe(out));
}

function dedupe(points) {
  const out = [];
  for (const p of points) {
    const last = out[out.length - 1];
    if (!last || last[0] !== p[0] || last[1] !== p[1]) out.push([p[0], p[1]]);
  }
  return out;
}

// Remove collinear interior points.
function simplify(points) {
  if (points.length < 3) return points;
  const out = [points[0]];
  for (let i = 1; i < points.length - 1; i++) {
    const a = out[out.length - 1];
    const b = points[i];
    const c = points[i + 1];
    const collinear = (a[0] === b[0] && b[0] === c[0]) || (a[1] === b[1] && b[1] === c[1]);
    if (!collinear) out.push(b);
  }
  out.push(points[points.length - 1]);
  return out;
}

// Dijkstra on the Hanan grid. Returns array of [x,y] or null.
function gridRoute(starts, goals, boxes, extra) {
  const xs = new Set();
  const ys = new Set();
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const b of boxes) {
    xs.add(b.x); xs.add(b.x + b.width);
    ys.add(b.y); ys.add(b.y + b.height);
    minX = Math.min(minX, b.x); maxX = Math.max(maxX, b.x + b.width);
    minY = Math.min(minY, b.y); maxY = Math.max(maxY, b.y + b.height);
  }
  for (const p of [...extra]) {
    xs.add(p[0]); ys.add(p[1]);
    minX = Math.min(minX, p[0]); maxX = Math.max(maxX, p[0]);
    minY = Math.min(minY, p[1]); maxY = Math.max(maxY, p[1]);
  }
  if (!Number.isFinite(minX)) return [starts[0], goals[0]];
  xs.add(minX - MARGIN); xs.add(maxX + MARGIN);
  ys.add(minY - MARGIN); ys.add(maxY + MARGIN);
  const X = [...xs].sort((a, b) => a - b);
  const Y = [...ys].sort((a, b) => a - b);
  const nx = X.length;
  const ny = Y.length;
  if (nx * ny > 400000) return null;
  const idx = (i, j) => i * ny + j;
  const xIndex = new Map(X.map((v, i) => [v, i]));
  const yIndex = new Map(Y.map((v, j) => [v, j]));

  // blocked[edge] for horizontal (dir 0/1) and vertical (dir 2/3) unit moves
  const inside = (mx, my) => {
    for (const b of boxes) {
      if (mx > b.x && mx < b.x + b.width && my > b.y && my < b.y + b.height) return true;
    }
    return false;
  };
  const hBlocked = new Uint8Array(Math.max(nx - 1, 0) * ny); // (i,j)-(i+1,j)
  for (let i = 0; i < nx - 1; i++) {
    const mx = (X[i] + X[i + 1]) / 2;
    for (let j = 0; j < ny; j++) hBlocked[i * ny + j] = inside(mx, Y[j]) ? 1 : 0;
  }
  const vBlocked = new Uint8Array(nx * Math.max(ny - 1, 0)); // (i,j)-(i,j+1)
  for (let i = 0; i < nx; i++) {
    for (let j = 0; j < ny - 1; j++) {
      vBlocked[i * (ny - 1) + j] = inside(X[i], (Y[j] + Y[j + 1]) / 2) ? 1 : 0;
    }
  }

  const goalSet = new Map();
  for (const g of goals) {
    const i = xIndex.get(g[0]);
    const j = yIndex.get(g[1]);
    if (i !== undefined && j !== undefined) goalSet.set(idx(i, j), g);
  }
  if (!goalSet.size) return null;

  // states: node*5 + dir, dir 0=+x 1=-x 2=+y 3=-y 4=start(no direction)
  const N = nx * ny * 5;
  const dist = new Float64Array(N).fill(Infinity);
  const prev = new Int32Array(N).fill(-1);
  const heap = new MinHeap();
  for (const s of starts) {
    const i = xIndex.get(s[0]);
    const j = yIndex.get(s[1]);
    if (i === undefined || j === undefined) continue;
    const st = idx(i, j) * 5 + 4;
    dist[st] = 0;
    heap.push(0, st);
  }
  const DX = [1, -1, 0, 0];
  const DY = [0, 0, 1, -1];
  let found = -1;
  while (heap.size) {
    const [d, st] = heap.pop();
    if (d > dist[st]) continue;
    const node = Math.floor(st / 5);
    const dir = st % 5;
    if (goalSet.has(node)) { found = st; break; }
    const i = Math.floor(node / ny);
    const j = node % ny;
    for (let k = 0; k < 4; k++) {
      const ni = i + DX[k];
      const nj = j + DY[k];
      if (ni < 0 || nj < 0 || ni >= nx || nj >= ny) continue;
      let blocked;
      let len;
      if (k < 2) {
        const e = Math.min(i, ni);
        blocked = hBlocked[e * ny + j];
        len = Math.abs(X[ni] - X[i]);
      } else {
        const e = Math.min(j, nj);
        blocked = vBlocked[i * (ny - 1) + e];
        len = Math.abs(Y[nj] - Y[j]);
      }
      if (blocked) continue;
      let cost = d + len;
      if (dir !== 4 && dir !== k) cost += BEND_PENALTY;
      const nst = idx(ni, nj) * 5 + k;
      if (cost < dist[nst]) {
        dist[nst] = cost;
        prev[nst] = st;
        heap.push(cost, nst);
      }
    }
  }
  if (found < 0) return null;
  const pts = [];
  for (let s = found; s !== -1; s = prev[s]) {
    const node = Math.floor(s / 5);
    pts.push([X[Math.floor(node / ny)], Y[node % ny]]);
  }
  pts.reverse();
  return pts;
}

class MinHeap {
  constructor() { this.a = []; }
  get size() { return this.a.length; }
  push(k, v) {
    const a = this.a;
    a.push([k, v]);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p][0] <= a[i][0]) break;
      [a[p], a[i]] = [a[i], a[p]];
      i = p;
    }
  }
  pop() {
    const a = this.a;
    const top = a[0];
    const last = a.pop();
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1;
        const r = l + 1;
        let m = i;
        if (l < a.length && a[l][0] < a[m][0]) m = l;
        if (r < a.length && a[r][0] < a[m][0]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]];
        i = m;
      }
    }
    return top;
  }
}

