// Standalone SVG export.
import { bboxOf, unionBox, centerOf } from './geometry.js';

export function escapeXml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

const num = (n) => (Number.isFinite(n) ? String(Math.round(n * 1000) / 1000) : '0');

function styleAttrs(style, defaults) {
  const s = { ...defaults, ...style };
  const parts = [];
  if (s.fill !== undefined) parts.push(`fill="${escapeXml(s.fill)}"`);
  if (s.stroke !== undefined) parts.push(`stroke="${escapeXml(s.stroke)}"`);
  if (s.strokeWidth !== undefined) parts.push(`stroke-width="${escapeXml(s.strokeWidth)}"`);
  if (s.opacity !== undefined) parts.push(`opacity="${escapeXml(s.opacity)}"`);
  return parts.join(' ');
}

function rotAttr(o, c) {
  return o.rotation ? ` transform="rotate(${num(o.rotation)} ${num(c.x)} ${num(c.y)})"` : '';
}

function textEl(text, x, y, style, extra = '') {
  const fill = style.color ?? '#000000';
  const size = style.fontSize ?? 14;
  const family = style.fontFamily ? ` font-family="${escapeXml(style.fontFamily)}"` : '';
  const lines = String(text).split('\n');
  const tspans = lines
    .map((l, i) => `<tspan x="${num(x)}" dy="${i === 0 ? 0 : '1.2em'}">${escapeXml(l)}</tspan>`)
    .join('');
  return `<text x="${num(x)}" y="${num(y)}" text-anchor="middle" dominant-baseline="middle" fill="${escapeXml(fill)}" font-size="${escapeXml(size)}"${family}${extra}>${tspans}</text>`;
}

export function toSVG(doc, { padding = 10 } = {}) {
  const pad = Number.isFinite(padding) ? padding : 10;
  const all = doc.elements().filter((e) => doc._isLayerVisible(e.layer));
  const shapes = all.filter((e) => e.type !== 'connector');
  const boxes = shapes.map(bboxOf);
  const routes = new Map();
  for (const c of all) if (c.type === 'connector') {
    const pts = doc.route(c.id);
    routes.set(c.id, pts);
    if (pts.length) boxes.push(unionBox(pts.map(([x, y]) => ({ x, y, width: 0, height: 0 }))));
  }
  const b = unionBox(boxes) ?? { x: 0, y: 0, width: 0, height: 0 };
  const vx = b.x - pad;
  const vy = b.y - pad;
  const vw = b.width + 2 * pad;
  const vh = b.height + 2 * pad;
  const parts = [];
  for (const e of all) {
    const id = escapeXml(e.id);
    const st = e.style ?? {};
    if (e.type === 'connector') {
      const pts = routes.get(e.id) ?? [];
      if (pts.length >= 2) {
        const d = pts.map(([x, y]) => `${num(x)},${num(y)}`).join(' ');
        parts.push(`<polyline data-id="${id}" points="${d}" fill="none" stroke="${escapeXml(st.stroke ?? '#000000')}" stroke-width="${escapeXml(st.strokeWidth ?? 1)}"${st.opacity !== undefined ? ` opacity="${escapeXml(st.opacity)}"` : ''}/>`);
        if (e.label) {
          const m = pts[Math.floor(pts.length / 2)];
          parts.push(textEl(e.label, m[0], m[1], st, ` data-label-for="${id}"`));
        }
      }
      continue;
    }
    const c = centerOf(e);
    const tr = rotAttr(e, c);
    const defaults = { fill: '#ffffff', stroke: '#000000', strokeWidth: 1 };
    const sa = styleAttrs(st, defaults);
    let body;
    switch (e.type) {
      case 'rect':
        body = `<rect x="${num(e.x)}" y="${num(e.y)}" width="${num(e.width)}" height="${num(e.height)}" ${sa}/>`;
        break;
      case 'ellipse':
        body = `<ellipse cx="${num(c.x)}" cy="${num(c.y)}" rx="${num(e.width / 2)}" ry="${num(e.height / 2)}" ${sa}/>`;
        break;
      case 'diamond': {
        const pts = [
          [c.x, e.y],
          [e.x + e.width, c.y],
          [c.x, e.y + e.height],
          [e.x, c.y],
        ].map(([x, y]) => `${num(x)},${num(y)}`).join(' ');
        body = `<polygon points="${pts}" ${sa}/>`;
        break;
      }
      case 'line':
        body = `<line x1="${num(e.x)}" y1="${num(e.y)}" x2="${num(e.x + e.width)}" y2="${num(e.y + e.height)}" ${sa.replace(/fill="[^"]*"/, '')}/>`;
        break;
      case 'image':
        body = e.src
          ? `<image href="${escapeXml(e.src)}" x="${num(e.x)}" y="${num(e.y)}" width="${num(e.width)}" height="${num(e.height)}" preserveAspectRatio="none"${st.opacity !== undefined ? ` opacity="${escapeXml(st.opacity)}"` : ''}/>`
          : `<rect x="${num(e.x)}" y="${num(e.y)}" width="${num(e.width)}" height="${num(e.height)}" fill="none" stroke="#999999"/>`;
        break;
      case 'text':
        body = '';
        break;
      default:
        body = `<rect x="${num(e.x)}" y="${num(e.y)}" width="${num(e.width)}" height="${num(e.height)}" ${sa}/>`;
    }
    if (body) {
      parts.push(`<g data-id="${id}"${tr}>${body.replace('<', `<`).replace(/^<(\w+)/, (m) => m)}</g>`);
    }
    if (e.text !== undefined && e.text !== null && e.text !== '') {
      parts.push(`<g data-id="${id}-text"${tr}>${textEl(e.text, c.x, c.y, st)}</g>`);
    }
  }
  const svgW = num(vw);
  const svgH = num(vh);
  return `<?xml version="1.0" encoding="UTF-8"?>\n<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" version="1.1" width="${svgW}" height="${svgH}" viewBox="${num(vx)} ${num(vy)} ${svgW} ${svgH}">\n${parts.join('\n')}\n</svg>\n`;
}

