// Auto-layout. "layered" wraps the vendored dagre (MIT, Sugiyama-style layered
// layout, see src/core/vendor/dagre/LICENSE.txt); "grid" is a simple packing.
import dagre from './vendor/dagre/dagre.esm.js';
import { DiagramError } from './errors.js';

// nodes: [{id, width, height}], edges: [[sourceId, targetId]] in input order.
// Returns Map id -> {x, y} (top-left corner).
export function layeredPositions(nodes, edges, opts = {}) {
  const direction = String(opts.direction ?? 'TB').toUpperCase();
  if (!['TB', 'LR', 'BT', 'RL'].includes(direction)) throw new DiagramError(`invalid direction: ${direction}`);
  const spacing = opts.spacing ?? 50;
  if (typeof spacing !== 'number' || !(spacing >= 0)) throw new DiagramError('invalid spacing');
  const g = new dagre.graphlib.Graph({ multigraph: false, compound: false });
  g.setGraph({ rankdir: direction, nodesep: spacing, ranksep: spacing, marginx: 0, marginy: 0 });
  g.setDefaultEdgeLabel(() => ({}));
  for (const n of nodes) g.setNode(n.id, { width: n.width, height: n.height });
  const seen = new Set();
  for (const [s, t] of edges) {
    if (s === t) continue;
    const key = s + '\u0000' + t;
    if (seen.has(key)) continue;
    seen.add(key);
    g.setEdge(s, t, {});
  }
  dagre.layout(g);
  const out = new Map();
  for (const n of nodes) {
    const p = g.node(n.id);
    out.set(n.id, { x: p.x - n.width / 2, y: p.y - n.height / 2 });
  }
  return out;
}

// Pack nodes into a near-square grid, in the given order, starting at origin.
export function gridPositions(nodes, opts = {}) {
  const gap = opts.gap ?? 40;
  const origin = opts.origin ?? { x: 0, y: 0 };
  const out = new Map();
  if (!nodes.length) return out;
  const cols = Math.ceil(Math.sqrt(nodes.length));
  const cellW = Math.max(...nodes.map((n) => n.width)) + gap;
  const cellH = Math.max(...nodes.map((n) => n.height)) + gap;
  nodes.forEach((n, i) => {
    const col = i % cols;
    const row = Math.floor(i / cols);
    out.set(n.id, { x: origin.x + col * cellW, y: origin.y + row * cellH });
  });
  return out;
}

