export function importDrawio(xml, opts = {}) {
  if (typeof xml !== 'string') throw new DiagramError('importDrawio expects a string');
  const tree = parseXml(xml);
  let model = findAll(tree, 'mxGraphModel')[0];
  if (!model) {
    const diagrams = findAll(tree, 'diagram');
    if (!diagrams.length) throw new DiagramError('not a draw.io document');
    const d = diagrams[0];
    model = d.children.find((c) => c.name === 'mxGraphModel');
    if (!model) {
      if (d.text.trim()) throw new DiagramError('compressed draw.io diagrams are not supported');
      throw new DiagramError('draw.io diagram has no mxGraphModel');
    }
  }
  const root = model.children.find((c) => c.name === 'root');
  if (!root) throw new DiagramError('mxGraphModel without root');
  const cells = findAll(root, 'mxCell');
  const byId = new Map();
  for (const c of cells) {
    const geom = c.children.find((x) => x.name === 'mxGeometry');
    byId.set(c.attrs.id, { cell: c, geom, attrs: c.attrs });
  }
  // absolute coordinates: child geometry is relative to a vertex parent
  const absOrigin = (id, depth = 0) => {
    const e = byId.get(id);
    if (!e || depth > 50 || !e.geom) return { x: 0, y: 0 };
    const p = byId.get(e.attrs.parent);
    const base = p && p.geom && p.attrs.vertex === '1' ? absOrigin(e.attrs.parent, depth + 1) : { x: 0, y: 0 };
    return { x: base.x + num(e.geom.attrs.x), y: base.y + num(e.geom.attrs.y) };
  };

  const doc = createDocument({ id: opts.id, actor: opts.actor });
  const vertexIds = new Set();
  const shapes = [];
  const edges = [];
  let z = 0;
  for (const c of cells) {
    const a = c.attrs;
    if (a.id === '0' || a.id === '1') continue;
    if (a.vertex === '1') {
      const e = byId.get(a.id);
      if (!e.geom) continue;
      const st = parseStyle(a.style);
      let type = 'rect';
      if (st.ellipse) type = 'ellipse';
      else if (st.rhombus) type = 'diamond';
      else if (st.image || st.shape === 'image') type = 'image';
      else if (st.text) type = 'text';
      const o = absOrigin(a.id);
      const element = {
        id: a.id,
        type,
        x: o.x,
        y: o.y,
        width: num(e.geom.attrs.width),
        height: num(e.geom.attrs.height),
        rotation: num(st.rotation),
        layer: DEFAULT_LAYER,
        z: z++,
        style: styleOf(st),
      };
      if (a.parent && byId.get(a.parent)?.attrs.vertex === '1') element.groupId = a.parent;
      const text = labelText(a.value);
      if (text) element.text = text;
      if (st.image || st.shape === 'image') {
        const img = st.image && st.image !== true ? st.image : null;
        if (img) element.src = img.replace(/^data:/, 'data:');
      }
      shapes.push(element);
      vertexIds.add(a.id);
    } else if (a.edge === '1') {
      edges.push(c);
    }
  }
  for (const c of edges) {
    const a = c.attrs;
    if (!vertexIds.has(a.source) || !vertexIds.has(a.target)) continue;
    const e = byId.get(a.id);
    const st = parseStyle(a.style);
    const pts = [];
    const arr = e.geom ? e.geom.children.find((x) => x.name === 'Array' && x.attrs.as === 'points') : null;
    if (arr) {
      for (const p of arr.children) if (p.name === 'mxPoint') pts.push([num(p.attrs.x), num(p.attrs.y)]);
    }
    const conn = {
      id: a.id,
      type: 'connector',
      source: { elementId: a.source },
      target: { elementId: a.target },
      routing: st.edgeStyle && /orthogonal/i.test(st.edgeStyle) ? 'orthogonal' : 'straight',
      waypoints: pts,
      layer: DEFAULT_LAYER,
      z: z++,
      style: styleOf(st),
    };
    const label = labelText(a.value);
    if (label) conn.label = label;
    edges.push(conn);
  }
  const connectors = edges.filter((x) => x && x.type === 'connector');
  doc.transaction(() => {
    for (const s of shapes) doc.apply({ type: 'add', element: s });
    for (const cn of connectors) doc.apply({ type: 'add', element: cn });
  });
  doc.clearHistory();
  return doc;
}

function styleOf(st) {
  const s = {};
  const map = {
    fillColor: 'fill',
    strokeColor: 'stroke',
    strokeWidth: 'strokeWidth',
    opacity: 'opacity',
    fontSize: 'fontSize',
    fontColor: 'color',
    fontFamily: 'fontFamily',
  };
  for (const [k, v] of Object.entries(map)) {
    if (st[k] !== undefined && st[k] !== 'none') {
      const val = ['strokeWidth', 'opacity', 'fontSize'].includes(v) ? num(st[k]) : st[k];
      s[v] = val;
    }
  }
  return s;
}

