// Document: validated operations are compiled into "writes" (puts/deletes on
// CRDT registers). Writes are turned into wire ops with fresh Lamport stamps,
// applied locally, buffered for sync, and recorded for undo as the inverse
// writes (prior register values captured before each write).
import { DiagramError } from './errors.js';
import {
  newState,
  applyWire,
  isAlive,
  materialize,
  cmpStamp,
  entityKey,
  DEFAULT_LAYER,
  KIND_EL,
  KIND_LAYER,
} from './state.js';
import { bboxOf, unionBox, containsPoint, snap as snapPoint } from './geometry.js';
import { computeRoute } from './routing.js';
import { layeredPositions, gridPositions } from './layout.js';
import { toSVG } from './svg.js';

export const SHAPE_TYPES = ['rect', 'ellipse', 'diamond', 'text', 'image', 'line'];
const TYPES = new Set([...SHAPE_TYPES, 'connector']);
const NUMERIC = ['x', 'y', 'width', 'height', 'rotation'];
const HISTORY_LIMIT = 500;
const ALIGN_MODES = ['left', 'center', 'right', 'top', 'middle', 'bottom'];

const rid = () => globalThis.crypto.randomUUID().replace(/-/g, '').slice(0, 16);
const clone = (v) => structuredClone(v);
const isNum = (v) => typeof v === 'number' && Number.isFinite(v);
const sameJSON = (a, b) => JSON.stringify(a) === JSON.stringify(b);

function numField(v, name, def) {
  if (v === undefined) return def;
  if (!isNum(v)) throw new DiagramError(`${name} must be a finite number`);
  return v;
}

function cmpId(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function validPoints(list) {
  if (list === undefined) return [];
  if (!Array.isArray(list)) throw new DiagramError('waypoints must be an array');
  return list.map((p) => {
    if (!Array.isArray(p) || !isNum(p[0]) || !isNum(p[1])) throw new DiagramError('invalid waypoint');
    return [p[0], p[1]];
  });
}

export class Document {
  constructor({ id, actor, state } = {}) {
    this.id = id ?? rid();
    this.actor = actor ?? rid();
    this.state = state ?? newState();
    this._listeners = new Map();
    this._pending = [];
    this._undo = [];
    this._redo = [];
    this._tx = null;
    this._cache = null;
    this._version = 0;
    if (!state) {
      applyWire(this.state, {
        opId: 'init:layer:' + DEFAULT_LAYER,
        actor: '',
        clock: 0,
        type: 'put',
        kind: KIND_LAYER,
        id: DEFAULT_LAYER,
        fields: { name: 'Default', visible: true, locked: false, order: 0 },
        create: true,
      });
    }
  }

  // ---------- events ----------
  on(evt, cb) {
    if (!this._listeners.has(evt)) this._listeners.set(evt, []);
    this._listeners.get(evt).push(cb);
    return this;
  }

  off(evt, cb) {
    const list = this._listeners.get(evt) ?? [];
    this._listeners.set(evt, list.filter((f) => f !== cb));
    return this;
  }

  _emit(evt, arg) {
    for (const cb of this._listeners.get(evt) ?? []) cb(arg);
  }

  // ---------- indexes ----------
  _index() {
    if (this._cache) return this._cache;
    const els = new Map();
    const layers = new Map();
    for (const ent of Object.values(this.state.entities)) {
      if (!isAlive(ent)) continue;
      if (ent.kind === KIND_LAYER) layers.set(ent.id, materialize(ent));
      else els.set(ent.id, materialize(ent));
    }
    const layerList = [...layers.values()].sort((a, b) => a.order - b.order || cmpId(a.id, b.id));
    const rank = new Map(layerList.map((l, i) => [l.id, i]));
    const rankOf = (lid) => (rank.has(lid) ? rank.get(lid) : rank.get(DEFAULT_LAYER) ?? -1);
    const sorted = [...els.values()].sort(
      (a, b) => rankOf(a.layer) - rankOf(b.layer) || a.z - b.z || cmpId(a.id, b.id),
    );
    this._cache = { els, layers, layerList, sorted };
    return this._cache;
  }

  _isLayerVisible(layerId) {
    const idx = this._index();
    const l = idx.layers.get(layerId) ?? idx.layers.get(DEFAULT_LAYER);
    return !l || l.visible !== false;
  }

  _need(id) {
    const o = this._index().els.get(id);
    if (!o) throw new DiagramError(`unknown id: ${id}`);
    return o;
  }

  _assertWritable(o) {
    const l = this._index().layers.get(o.layer);
    if (l && l.locked) throw new DiagramError(`layer ${o.layer} is locked`);
  }

  _checkEndpoint(ref) {
    if (!ref || typeof ref !== 'object' || typeof ref.elementId !== 'string') {
      throw new DiagramError('invalid connector endpoint');
    }
    const t = this._index().els.get(ref.elementId);
    if (!t || t.type === 'connector') throw new DiagramError(`unknown endpoint: ${ref.elementId}`);
  }

  _topZ() {
    let m = -1;
    for (const e of this._index().els.values()) m = Math.max(m, e.z);
    return m;
  }

  // ---------- public operations ----------
  apply(op) {
    this._commit(this._plan(op));
  }

  transaction(fn) {
    if (this._tx) return fn(this);
    this._tx = [];
    let result;
    try {
      result = fn(this);
    } catch (e) {
      const partial = this._tx;
      this._tx = null;
      if (partial.length) this._applyWrites(partial);
      throw e;
    }
    const unit = this._tx;
    this._tx = null;
    if (unit.length) this._record(unit);
    return result;
  }

  undo() {
    if (!this._undo.length) return false;
    const u = this._undo.pop();
    const redo = this._applyWrites(u.writes);
    this._redo.push({ writes: redo });
    return true;
  }

  redo() {
    if (!this._redo.length) return false;
    const r = this._redo.pop();
    const undo = this._applyWrites(r.writes);
    this._undo.push({ writes: undo });
    return true;
  }

  canUndo() { return this._undo.length > 0; }
  canRedo() { return this._redo.length > 0; }
  clearHistory() { this._undo = []; this._redo = []; }

  pendingOps() {
    const out = this._pending;
    this._pending = [];
    return out;
  }

  receive(ops) {
    const list = Array.isArray(ops) ? ops : [ops];
    let n = 0;
    for (const op of list) if (applyWire(this.state, op)) n++;
    if (n) this._touch();
    return n;
  }

  hasOp(opId) {
    return !!this.state.seen[opId];
  }

  // ---------- queries ----------
  get(id) {
    const o = this._index().els.get(id);
    return o ? clone(o) : undefined;
  }

  elements(filter = {}) {
    return this._index()
      .sorted.filter(
        (e) =>
          (filter.layer === undefined || e.layer === filter.layer) &&
          (filter.type === undefined || e.type === filter.type),
      )
      .map(clone);
  }

  hitTest(x, y) {
    const sorted = this._index().sorted;
    for (let i = sorted.length - 1; i >= 0; i--) {
      const e = sorted[i];
      if (e.type === 'connector' || !this._isLayerVisible(e.layer)) continue;
      if (containsPoint(e, x, y)) return clone(e);
    }
    return null;
  }

  select(rect) {
    if (!rect || !isNum(rect.x) || !isNum(rect.y) || !isNum(rect.width) || !isNum(rect.height)) {
      throw new DiagramError('select expects a rect {x,y,width,height}');
    }
    const r = rect;
    return this._index()
      .sorted.filter((e) => {
        if (e.type === 'connector' || !this._isLayerVisible(e.layer)) return false;
        const b = bboxOf(e);
        return b.x >= r.x && b.y >= r.y && b.x + b.width <= r.x + r.width && b.y + b.height <= r.y + r.height;
      })
      .map(clone);
  }

  bounds(ids) {
    const idx = this._index();
    let list;
    if (ids === undefined) list = idx.sorted;
    else {
      if (!Array.isArray(ids)) throw new DiagramError('bounds expects an array of ids');
      list = ids.map((id) => this._need(id));
    }
    const boxes = [];
    for (const e of list) {
      if (e.type === 'connector') {
        for (const [x, y] of this.route(e.id)) boxes.push({ x, y, width: 0, height: 0 });
      } else boxes.push(bboxOf(e));
    }
    return unionBox(boxes);
  }

  route(connectorId) {
    const idx = this._index();
    const c = idx.els.get(connectorId);
    if (!c || c.type !== 'connector') throw new DiagramError(`unknown connector: ${connectorId}`);
    return computeRoute(c, idx.els);
  }

  // ---------- geometry operations ----------
  align(ids, mode) {
    if (!ALIGN_MODES.includes(mode)) throw new DiagramError(`invalid align mode: ${mode}`);
    const shapes = this._shapeList(ids);
    if (!shapes.length) return;
    shapes.forEach((s) => this._assertWritable(s));
    const boxes = shapes.map(bboxOf);
    const sel = unionBox(boxes);
    const writes = [];
    shapes.forEach((s, i) => {
      const b = boxes[i];
      let dx = 0;
      let dy = 0;
      if (mode === 'left') dx = sel.x - b.x;
      else if (mode === 'right') dx = sel.x + sel.width - (b.x + b.width);
      else if (mode === 'center') dx = sel.x + sel.width / 2 - (b.x + b.width / 2);
      else if (mode === 'top') dy = sel.y - b.y;
      else if (mode === 'bottom') dy = sel.y + sel.height - (b.y + b.height);
      else if (mode === 'middle') dy = sel.y + sel.height / 2 - (b.y + b.height / 2);
      if (dx || dy) writes.push(this._w(s.id, { x: s.x + dx, y: s.y + dy }));
    });
    this._run(writes);
  }

  distribute(ids, dir) {
    if (dir !== 'horizontal' && dir !== 'vertical') throw new DiagramError(`invalid distribute direction: ${dir}`);
    const shapes = this._shapeList(ids);
    if (shapes.length < 3) return;
    shapes.forEach((s) => this._assertWritable(s));
    const h = dir === 'horizontal';
    const items = shapes
      .map((s) => ({ s, b: bboxOf(s) }))
      .sort((p, q) => (h ? p.b.x - q.b.x : p.b.y - q.b.y) || cmpId(p.s.id, q.s.id));
    const size = (b) => (h ? b.width : b.height);
    const pos = (b) => (h ? b.x : b.y);
    const n = items.length;
    const start = pos(items[0].b);
    const end = pos(items[n - 1].b) + size(items[n - 1].b);
    const sumSize = items.reduce((acc, it) => acc + size(it.b), 0);
    const gap = (end - start - sumSize) / (n - 1);
    const writes = [];
    let cur = start + size(items[0].b) + gap;
    for (let i = 1; i < n - 1; i++) {
      const { s, b } = items[i];
      const d = cur - pos(b);
      if (d) writes.push(this._w(s.id, h ? { x: s.x + d } : { y: s.y + d }));
      cur += size(b) + gap;
    }
    this._run(writes);
  }

  layout(kind, opts = {}) {
    const idx = this._index();
    const shapes = idx.sorted.filter((e) => e.type !== 'connector');
    shapes.forEach((s) => this._assertWritable(s));
    let pos;
    if (kind === 'layered') {
      const ids = new Set(shapes.map((s) => s.id));
      const nodes = shapes.map((s) => ({ id: s.id, width: s.width, height: s.height }));
      const edges = [...idx.els.values()]
        .filter((c) => c.type === 'connector' && ids.has(c.source.elementId) && ids.has(c.target.elementId))
        .map((c) => [c.source.elementId, c.target.elementId]);
      pos = layeredPositions(nodes, edges, { direction: opts.direction ?? 'TB', spacing: opts.spacing ?? 50 });
    } else if (kind === 'grid') {
      const nodes = shapes.map((s) => ({ id: s.id, width: s.width, height: s.height }));
      const b = unionBox(shapes.map(bboxOf));
      pos = gridPositions(nodes, { gap: opts.spacing ?? 40, origin: b ? { x: b.x, y: b.y } : { x: 0, y: 0 } });
    } else {
      throw new DiagramError(`unknown layout: ${kind}`);
    }
    const writes = [];
    for (const s of shapes) {
      const p = pos.get(s.id);
      if (p && (p.x !== s.x || p.y !== s.y)) writes.push(this._w(s.id, { x: p.x, y: p.y }));
    }
    this._run(writes);
  }

  // ---------- serialization ----------
  toJSON() {
    const idx = this._index();
    return {
      format: 'diagram-s5',
      version: 1,
      id: this.id,
      clock: this.state.clock,
      layers: idx.layerList.map(clone),
      elements: idx.sorted.map(clone),
      state: clone(this.state),
    };
  }

  // Replace the document content with a snapshot, emitting the needed ops.
  restore(snapshot) {
    const snap = typeof snapshot === 'string' ? parseSnapshot(snapshot) : snapshot;
    if (!snap || !Array.isArray(snap.elements) || !Array.isArray(snap.layers)) {
      throw new DiagramError('invalid snapshot');
    }
    const idx = this._index();
    const writes = [];
    const wantLayers = new Set(snap.layers.map((l) => l.id));
    for (const l of snap.layers) {
      const cur = idx.layers.get(l.id);
      const target = layerFields(l);
      if (!cur) writes.push({ type: 'put', kind: KIND_LAYER, id: l.id, fields: target, create: true });
      else {
        const f = diffFields(cur, target);
        if (Object.keys(f).length) writes.push({ type: 'put', kind: KIND_LAYER, id: l.id, fields: f });
      }
    }
    for (const cur of idx.layers.values()) {
      if (!wantLayers.has(cur.id) && cur.id !== DEFAULT_LAYER) writes.push({ type: 'del', kind: KIND_LAYER, id: cur.id });
    }
    const wantEls = new Set(snap.elements.map((e) => e.id));
    for (const e of snap.elements) {
      const cur = idx.els.get(e.id);
      const target = elementFields(e);
      if (!cur) writes.push({ type: 'put', kind: KIND_EL, id: e.id, fields: target, create: true });
      else {
        const f = diffElementFields(cur, e);
        if (Object.keys(f).length) writes.push({ type: 'put', kind: KIND_EL, id: e.id, fields: f });
      }
    }
    for (const cur of idx.els.values()) {
      if (!wantEls.has(cur.id)) writes.push({ type: 'del', kind: KIND_EL, id: cur.id });
    }
    this._run(writes);
    return writes.length;
  }

  toSVG(opts = {}) {
    return toSVG(this, opts);
  }

  // ---------- planning (validation -> writes) ----------
  _plan(op) {
    if (!op || typeof op !== 'object') throw new DiagramError('operation must be an object');
    switch (op.type) {
      case 'add': return this._planAdd(op.element);
      case 'update': return this._planUpdate(op.id, op.patch);
      case 'remove': return this._planRemove(op.id);
      case 'move': return this._planMove(op.ids, op.dx, op.dy);
      case 'resize': return this._planResize(op.id, op.box, !!op.keepAspect);
      case 'rotate': return this._planRotate(op.id, op.deg);
      case 'group': return this._planGroup(op.ids, op.groupId);
      case 'ungroup': return this._planUngroup(op.groupId);
      case 'reorder': return this._planReorder(op.id, op.to);
      case 'addLayer': return this._planAddLayer(op.layer);
      case 'updateLayer': return this._planUpdateLayer(op.id, op.patch);
      case 'removeLayer': return this._planRemoveLayer(op.id);
      case 'setStyle': return this._planSetStyle(op.ids, op.style);
      default: throw new DiagramError(`unknown operation type: ${op.type}`);
    }
  }

  _w(id, fields) {
    return { type: 'put', kind: KIND_EL, id, fields };
  }

  _shapeList(ids) {
    if (!Array.isArray(ids)) throw new DiagramError('expected an array of ids');
    const seen = new Set();
    const out = [];
    for (const id of ids) {
      if (seen.has(id)) continue;
      seen.add(id);
      const o = this._need(id);
      if (o.type !== 'connector') out.push(o);
    }
    return out;
  }

  _planAdd(el) {
    if (!el || typeof el !== 'object') throw new DiagramError('add requires an element');
    if (typeof el.id !== 'string' || !el.id) throw new DiagramError('element id must be a non-empty string');
    if (!TYPES.has(el.type)) throw new DiagramError(`unknown element type: ${el.type}`);
    const idx = this._index();
    if (idx.els.has(el.id)) throw new DiagramError(`duplicate id: ${el.id}`);
    const layerId = el.layer ?? DEFAULT_LAYER;
    const layer = idx.layers.get(layerId);
    if (!layer) throw new DiagramError(`unknown layer: ${layerId}`);
    if (layer.locked) throw new DiagramError(`layer ${layerId} is locked`);
    const fields = {};
    for (const [k, v] of Object.entries(el)) {
      if (k === 'id' || k === 'style' || k === 'type' || v === undefined || v === null) continue;
      fields[k] = clone(v);
    }
    fields.type = el.type;
    fields.layer = layerId;
    if (el.groupId !== undefined && el.groupId !== null) fields.groupId = String(el.groupId);
    if (el.type === 'connector') {
      this._checkEndpoint(el.source);
      this._checkEndpoint(el.target);
      fields.source = clone(el.source);
      fields.target = clone(el.target);
      if (el.routing !== undefined && !['straight', 'orthogonal'].includes(el.routing)) {
        throw new DiagramError(`invalid routing: ${el.routing}`);
      }
      fields.routing = el.routing ?? 'straight';
      fields.waypoints = validPoints(el.waypoints);
    } else {
      for (const k of NUMERIC) fields[k] = numField(el[k], k, 0);
    }
    fields.z = numField(el.z, 'z', this._topZ() + 1);
    if (el.style && typeof el.style === 'object') {
      for (const [k, v] of Object.entries(el.style)) if (v !== undefined && v !== null) fields['style.' + k] = clone(v);
    }
    return [{ type: 'put', kind: KIND_EL, id: el.id, fields, create: true }];
  }

  _planUpdate(id, patch) {
    const o = this._need(id);
    if (!patch || typeof patch !== 'object') throw new DiagramError('update requires a patch object');
    this._assertWritable(o);
    const fields = {};
    for (const [k, v] of Object.entries(patch)) {
      if (v === undefined) continue;
      if (k === 'id') throw new DiagramError('cannot change element id');
      if (k === 'type') {
        if (v !== o.type) throw new DiagramError('cannot change element type');
        continue;
      }
      if (k === 'style') {
        if (v && typeof v === 'object') {
          for (const [sk, sv] of Object.entries(v)) fields['style.' + sk] = sv === undefined || sv === null ? null : clone(sv);
        }
        continue;
      }
      if (NUMERIC.includes(k)) numField(v, k, 0);
      if (k === 'layer') {
        const l = this._index().layers.get(v);
        if (!l) throw new DiagramError(`unknown layer: ${v}`);
        if (l.locked) throw new DiagramError(`layer ${v} is locked`);
      }
      if (k === 'source' || k === 'target') {
        if (o.type !== 'connector') throw new DiagramError(`${k} only applies to connectors`);
        this._checkEndpoint(v);
      }
      if (k === 'waypoints') validPoints(v);
      if (k === 'routing' && v !== null && !['straight', 'orthogonal'].includes(v)) {
        throw new DiagramError(`invalid routing: ${v}`);
      }
      fields[k] = v === null ? null : clone(v);
    }
    return Object.keys(fields).length ? [this._w(id, fields)] : [];
  }

  _planRemove(id) {
    const o = this._need(id);
    this._assertWritable(o);
    const writes = [{ type: 'del', kind: KIND_EL, id }];
    for (const c of this._index().els.values()) {
      if (c.type !== 'connector' || c.id === id) continue;
      if (c.source.elementId === id || c.target.elementId === id) {
        this._assertWritable(c);
        writes.push({ type: 'del', kind: KIND_EL, id: c.id });
      }
    }
    return writes;
  }

  _planMove(ids, dx, dy) {
    if (!Array.isArray(ids)) throw new DiagramError('move expects an array of ids');
    if (!isNum(dx) || !isNum(dy)) throw new DiagramError('move expects numeric dx, dy');
    const seen = new Set();
    const writes = [];
    for (const id of ids) {
      if (seen.has(id)) continue;
      seen.add(id);
      const o = this._need(id);
      this._assertWritable(o);
      if (o.type === 'connector') {
        writes.push(this._w(id, { waypoints: o.waypoints.map(([x, y]) => [x + dx, y + dy]) }));
      } else {
        writes.push(this._w(id, { x: o.x + dx, y: o.y + dy }));
      }
    }
    return writes;
  }

  _planResize(id, box, keepAspect) {
    const o = this._need(id);
    if (o.type === 'connector') throw new DiagramError('cannot resize a connector');
    this._assertWritable(o);
    if (!box || !isNum(box.x) || !isNum(box.y) || !isNum(box.width) || !isNum(box.height)) {
      throw new DiagramError('resize expects box {x,y,width,height}');
    }
    if (box.width < 0 || box.height < 0) throw new DiagramError('negative size');
    let w = box.width;
    let h = box.height;
    if (keepAspect && o.width > 0 && o.height > 0) {
      const s = Math.min(w / o.width, h / o.height);
      w = o.width * s;
      h = o.height * s;
    }
    return [this._w(id, { x: box.x, y: box.y, width: w, height: h })];
  }

  _planRotate(id, deg) {
    const o = this._need(id);
    if (o.type === 'connector') throw new DiagramError('cannot rotate a connector');
    this._assertWritable(o);
    numField(deg, 'deg', 0);
    return [this._w(id, { rotation: deg })];
  }

  _planGroup(ids, groupId) {
    if (groupId !== undefined && (typeof groupId !== 'string' || !groupId)) throw new DiagramError('invalid groupId');
    const shapes = this._shapeList(ids);
    if (!shapes.length) return [];
    shapes.forEach((s) => this._assertWritable(s));
    const gid = groupId ?? 'group-' + rid().slice(0, 10);
    return shapes.map((s) => this._w(s.id, { groupId: gid }));
  }

  _planUngroup(groupId) {
    const members = [...this._index().els.values()].filter((e) => e.groupId === groupId);
    members.forEach((m) => this._assertWritable(m));
    return members.map((m) => this._w(m.id, { groupId: null }));
  }

  _planReorder(id, to) {
    const o = this._need(id);
    this._assertWritable(o);
    if (!['front', 'back', 'forward', 'backward'].includes(to)) throw new DiagramError(`invalid reorder target: ${to}`);
    const sib = [...this._index().els.values()]
      .filter((e) => e.layer === o.layer)
      .sort((a, b) => a.z - b.z || cmpId(a.id, b.id));
    const i = sib.findIndex((e) => e.id === id);
    const zs = sib.map((e) => e.z);
    let z;
    if (to === 'front') z = Math.max(...zs) + 1;
    else if (to === 'back') z = Math.min(...zs) - 1;
    else if (to === 'forward') {
      if (i >= sib.length - 1) return [];
      const a = sib[i + 1].z;
      const b = i + 2 < sib.length ? sib[i + 2].z : a + 2;
      z = (a + b) / 2;
    } else {
      if (i <= 0) return [];
      const b = sib[i - 1].z;
      const a = i - 2 >= 0 ? sib[i - 2].z : b - 2;
      z = (a + b) / 2;
    }
    if (z === o.z) return [];
    return [this._w(id, { z })];
  }

  _planAddLayer(layer) {
    if (!layer || typeof layer !== 'object' || typeof layer.id !== 'string' || !layer.id) {
      throw new DiagramError('addLayer requires layer.id');
    }
    const idx = this._index();
    if (idx.layers.has(layer.id)) throw new DiagramError(`duplicate layer: ${layer.id}`);
    let maxOrder = -1;
    for (const l of idx.layers.values()) maxOrder = Math.max(maxOrder, l.order);
    const fields = {
      name: layer.name ?? layer.id,
      visible: layer.visible ?? true,
      locked: layer.locked ?? false,
      order: numField(layer.order, 'order', maxOrder + 1),
    };
    return [{ type: 'put', kind: KIND_LAYER, id: layer.id, fields, create: true }];
  }

  _planUpdateLayer(id, patch) {
    const l = this._index().layers.get(id);
    if (!l) throw new DiagramError(`unknown layer: ${id}`);
    if (!patch || typeof patch !== 'object') throw new DiagramError('updateLayer requires a patch');
    const fields = {};
    for (const [k, v] of Object.entries(patch)) {
      if (v === undefined || k === 'id') continue;
      if (k === 'order') numField(v, 'order', 0);
      fields[k] = clone(v);
    }
    return Object.keys(fields).length ? [{ type: 'put', kind: KIND_LAYER, id, fields }] : [];
  }

  _planRemoveLayer(id) {
    const idx = this._index();
    const l = idx.layers.get(id);
    if (!l) throw new DiagramError(`unknown layer: ${id}`);
    if (id === DEFAULT_LAYER) throw new DiagramError('cannot remove the default layer');
    if (l.locked) throw new DiagramError(`layer ${id} is locked`);
    const writes = [];
    for (const e of idx.els.values()) {
      if (e.layer === id) writes.push(this._w(e.id, { layer: DEFAULT_LAYER }));
    }
    writes.push({ type: 'del', kind: KIND_LAYER, id });
    return writes;
  }

  _planSetStyle(ids, style) {
    if (!style || typeof style !== 'object') throw new DiagramError('setStyle requires a style object');
    const shapes = [];
    const seen = new Set();
    for (const id of ids ?? []) {
      if (seen.has(id)) continue;
      seen.add(id);
      shapes.push(this._need(id));
    }
    const writes = [];
    for (const o of shapes) {
      this._assertWritable(o);
      const fields = {};
      for (const [k, v] of Object.entries(style)) fields['style.' + k] = v === undefined || v === null ? null : clone(v);
      if (Object.keys(fields).length) writes.push(this._w(o.id, fields));
    }
    return writes;
  }

  // ---------- writing ----------
  _run(writes) {
    this.transaction(() => this._commit(writes));
  }

  _commit(writes) {
    if (!writes.length) return;
    const inv = this._applyWrites(writes);
    if (this._tx) this._tx.unshift(...inv);
    else if (inv.length) this._record(inv);
  }

  _record(writes) {
    this._undo.push({ writes });
    if (this._undo.length > HISTORY_LIMIT) this._undo.shift();
    this._redo = [];
  }

  _touch() {
    this._cache = null;
    this._version++;
  }

  // Apply writes, emitting wire ops; returns the inverse writes (already in apply order).
  _applyWrites(writes) {
    const priors = [];
    for (const w of writes) {
      const prior = this._priorOf(w);
      const clock = this.state.clock + 1;
      const wire = { opId: `${this.actor}:${clock}:${rid()}`, actor: this.actor, clock, type: w.type, kind: w.kind, id: w.id };
      if (w.type === 'put') {
        wire.fields = clone(w.fields);
        if (w.create) wire.create = true;
      }
      applyWire(this.state, wire);
      this._touch();
      this._pending.push(wire);
      this._emit('op', wire);
      if (prior) priors.push(prior);
    }
    return priors.reverse();
  }

  _priorOf(w) {
    const ent = this.state.entities[entityKey(w.kind, w.id)];
    const alive = !!ent && isAlive(ent);
    if (w.type === 'del') {
      if (!alive) return null;
      const fields = {};
      for (const [f, r] of Object.entries(ent.fields)) fields[f] = clone(r.v);
      return { type: 'put', kind: w.kind, id: w.id, fields, create: true };
    }
    if (w.create && !alive) return { type: 'del', kind: w.kind, id: w.id };
    const fields = {};
    for (const f of Object.keys(w.fields)) {
      const cur = ent?.fields[f];
      fields[f] = cur ? clone(cur.v) : null;
    }
    return { type: 'put', kind: w.kind, id: w.id, fields };
  }

  // ---------- snapshot-based helpers ----------
  _applySnapshotDirect(snapshot) {
    // used by fromJSON for plain (stateless) snapshots: writes with the zero stamp
    let n = 0;
    const put = (kind, id, fields, create) => {
      applyWire(this.state, { opId: `snap:${kind}:${id}:${n++}`, actor: '', clock: 0, type: 'put', kind, id, fields, create });
    };
    for (const l of snapshot.layers ?? []) put(KIND_LAYER, l.id, layerFields(l), true);
    for (const e of snapshot.elements ?? []) put(KIND_EL, e.id, elementFields(e), true);
    this.state.clock = Math.max(this.state.clock, snapshot.clock ?? 0);
    this._touch();
  }
}

function layerFields(l) {
  const f = {};
  for (const [k, v] of Object.entries(l)) if (k !== 'id' && v !== undefined) f[k] = clone(v);
  return f;
}

function elementFields(e) {
  const f = {};
  for (const [k, v] of Object.entries(e)) {
    if (k === 'id' || v === undefined) continue;
    if (k === 'style') {
      for (const [sk, sv] of Object.entries(v ?? {})) if (sv !== null && sv !== undefined) f['style.' + sk] = clone(sv);
    } else f[k] = clone(v);
  }
  return f;
}

function diffFields(cur, target) {
  const out = {};
  for (const k of Object.keys(target)) if (!sameJSON(cur[k], target[k])) out[k] = clone(target[k]);
  for (const k of Object.keys(cur)) if (k !== 'id' && !(k in target)) out[k] = null;
  return out;
}

function diffElementFields(cur, target) {
  const want = elementFields(target);
  const out = {};
  const curFlat = {};
  for (const [k, v] of Object.entries(cur)) {
    if (k === 'id') continue;
    if (k === 'style') for (const [sk, sv] of Object.entries(v)) curFlat['style.' + sk] = sv;
    else curFlat[k] = v;
  }
  for (const [k, v] of Object.entries(want)) if (!sameJSON(curFlat[k], v)) out[k] = clone(v);
  for (const k of Object.keys(curFlat)) if (!(k in want) && curFlat[k] !== null && curFlat[k] !== undefined) out[k] = null;
  return out;
}

function parseSnapshot(text) {
  try {
    return JSON.parse(text);
  } catch {
    throw new DiagramError('snapshot is not valid JSON');
  }
}

export function createDocument({ id, actor } = {}) {
  return new Document({ id, actor });
}

export function fromJSON(json, { actor } = {}) {
  const snap = typeof json === 'string' ? parseSnapshot(json) : json;
  if (!snap || typeof snap !== 'object' || snap.format !== 'diagram-s5') {
    throw new DiagramError('not a diagram-s5 document');
  }
  if (snap.state) {
    return new Document({ id: snap.id, actor, state: clone(snap.state) });
  }
  const doc = new Document({ id: snap.id, actor });
  doc._applySnapshotDirect(snap);
  return doc;
}

